input.sparql:
SELECT ?point ?tsid ?class WHERE {
  ?point a ?class .
  ?point ref:hasTimeseriesId ?tsid .
  FILTER(str(?class) CONTAINS "Power" || str(?class) CONTAINS "Occupancy")
}

SELECT ?point ?tsid ?class WHERE {
  ?point a ?class .
  ?point ref:hasTimeseriesId ?tsid .
  { ?point a brick:Electric_Power_Sensor } UNION { ?point a brick:Occupancy_Sensor }
}

